import shutil
import subprocess

def cmd_path(name):
    return shutil.which(name) or ''

def run_command(argv):
    return subprocess.run(argv, shell=False)

def check():
    path = cmd_path('bash')
    return run_command([path, '--version'])

import subprocess

def resolve_tool():
    return input('tool: ')

subprocess.run([resolve_tool(), '--version'])
subprocess.check_output(['python3', '--version'], executable=resolve_tool())
